// GH-489 SNK-R30: one red-arm switch readable in the BROWSER (`?obArm=<name>` on
// the app URL — the construction gate's convention) and in NODE (`OB_ARM=<a,b>`
// in the environment — the node gates' convention). Used by the arms this round
// adds (drop-dedupe, flip-cap, band-law-off, board-inject); the older arms keep
// their own URL regexes, nothing about them moves. An arm is never on by default.
const obArmIgnored = new Set(); // SNK-R37 L3: each ignored arm is named once per boot
export function obArmOn(name) {
  try {
    const q = (typeof location !== 'undefined' && location && location.search) || '';
    if (new RegExp('(?:\\?|&)obArm=' + name + '(?:&|$)').test(q)) {
      // GH-489 SNK-R37 (landing rule L3, the lighting lane's ruling): a URL arm
      // fires only on a SCRIPTED boot — the app's own gate (`?obtool` / `?cinema`,
      // `=0` opts out, the sessionStorage carry main.js writes). A default boot
      // renders byte-identically with the flag present; the ignored arm is named.
      const bq = new URLSearchParams(q);
      const on = (k) => bq.has(k) && bq.get(k) !== '0';
      let scripted = on('obtool') || on('cinema');
      try { if (!scripted && bq.get('obtool') !== '0') scripted = sessionStorage.getItem('ob-scripted') === '1'; } catch (e) { /* storage unavailable */ }
      if (scripted) return true;
      if (!obArmIgnored.has(name)) { obArmIgnored.add(name); try { console.warn(`[arm] ?obArm=${name} ignored — not a scripted boot (no ?obtool / ?cinema); the app renders its default`); } catch (e) { /* no console */ } }
      return false;
    }
  } catch (e) { /* no location in this host */ }
  try {
    const env = (typeof process !== 'undefined' && process && process.env && process.env.OB_ARM) || '';
    return env.split(',').map((s) => s.trim()).includes(name);
  } catch (e) { return false; }
}

