        leatherThickness: 0.00118,
        legTopMeasured: [[0.0, 40.3], [0.16, 44.7], [0.26, 49.8], [0.47, 47.1], [0.90, 45.4], [1.0, 44.6]],
        crestFade: [[0, 1.0], [22, 0.99], [37, 0.58], [52, 0.56], [67, 0.54], [82, 0.35], [90, 0.35]],
        // D621-PLAN-2 (O21 closed): the TOP SURFACE per station, read straight
