      bedAboveFloor: 0.753, roomFloor: true,
      sightInset: 0.0936625, // FT-SIGHTS inset_from_nose 93.6625 mm
      sight: { r: 0.006, elong: 1, dot: true }, // FT-SIGHTS r6 round inlays
