/** Spec for a table id, falling back to the KERNEL-default entry for
 * unknown ids (mirrors the kernel's serde fill, NOT the app default). */
export const specFor = (id) => TABLE_SPECS[id] ?? TABLE_SPECS[SCRIPTED_PIN_TABLE_ID];

/** The table id the scene is currently built for (buildTable/rebuild).
 * look.js consumes this through a namespace import so its tournament regrade skips
 * repainting branded factory materials. */
let _activeTableId = SCRIPTED_PIN_TABLE_ID;
export const activeTableId = () => _activeTableId;

// ORDER-SNK-COMPANION-ENVELOPE-CACHE (review 775r12 P2 on #637, class E1): the
// collar envelope (pocketCollarEnvelope) is a pure function of the BUILT table —
// its spec and the throat-off arm — yet every call rebuilt the four ≈ 32,600-
// vertex corner caps and sorted their bearings (node: cold 188 ms, warm 89–106
// ms), and sinkIndex() → buildSinkPivot() asked for it on every potted ball.
// Memoised per build: computed lazily on the first read, deep-frozen, returned
// by identity until buildTable() / rebuild() drop it (the per-build reset
// precedent of cn8SinkSpecs / cn8MouthLamp / sinkRestSpecs). Read and written by
// pocketCollarEnvelope alone; the two build sites only reset it to null.
// shape: { id, value: the frozen per-pocket array } | null
let _collarEnvMemo = null;
// Ruling (C) of the same order: the one cold build per table build moves OFF the
// pot path — right after each memo reset the build is scheduled for idle time
// (requestIdleCallback when the host has it, else setTimeout 0; browser-only:
// without a `window` nothing is scheduled, so node's build path — instruments,
// tests — is untouched). The lazy build in pocketCollarEnvelope stays the
// fallback for a pot that arrives before the idle tick; correctness never
// depends on the pre-warm, and a pre-warm that throws is swallowed and logged
// once. Non-snooker tables and the throat-off arm schedule nothing: the same
// early returns decide before any scheduling.
let _collarEnvPrewarmWarned = false;
function collarEnvelopePrewarm(id) {
  if (typeof window === 'undefined') return false;
  const g = globalThis;
  const ric = typeof g.requestIdleCallback === 'function' ? g.requestIdleCallback : null;
  const sto = typeof g.setTimeout === 'function' ? g.setTimeout : null;
  if (!ric && !sto) return false;
  const spec = specFor(id);
  if (!spec || !spec.kernel.template || spec.render.style !== 'snooker') return false;
  if (obArmOn('throat-off')) return false;
  const run = () => {
    // a rebuild that landed before this tick owns the memo now; this tick builds nothing
    if (_activeTableId !== id) return;
    try {
      pocketCollarEnvelope(id);
    } catch (e) {
      if (!_collarEnvPrewarmWarned) {
        _collarEnvPrewarmWarned = true;
        console.warn('[collar-envelope] idle pre-warm failed once (the lazy build on the first pot stands):', e && e.message ? e.message : e);
      }
    }
  };
  if (ric) ric(run, { timeout: 500 }); else sto(run, 0);
  return true;
}

// ---- CEBP 2005/6 template constants (catalog v7 Amendment A1): literal
// mirror of the kernel `cebp` module (crates/pool-core/src/table.rs) — the
// label-exact inch values of the WPBSA corner/middle construction drawings.
// Do not tweak independently of the kernel.
const CEBP = (() => {
  const IN = 0.0254;
  return {
    cornerTangency: (5.43 - 1.875) * IN, // rail↔arc1 tangency from corner
    cornerR1: 3.00 * IN, cornerR2: 4.50 * IN, cornerFallR: 3.50 * IN,
    cornerFallOff: 1.875 * IN, // fall centre = slate-edge intersection
    cornerJunction: Math.PI / 2 + Math.atan2(6.15 - 5.43, 4.32 - 3.00),
    middleTangency: 4.344 * IN,
    middleR1: 3.125 * IN, middleR2: 2.094 * IN, middleFallR: 2.094 * IN,
    middleFallDepth: (1.875 + 0.156) * IN,
    middleJunction: 54 * Math.PI / 180,
  };
})();

// ---- Chinese-eight molded-mouth KERNEL corner-family mirror: literal twin
// of the kernel `cn8` module (crates/pool-core/src/table.rs). The kernel
// corners depart the nose line at the F2 departure and run onto the Ø105
// mouth-circle capture disc about the drawing O_f = ±(L/2 + C), ±(W/2 + C)
// — the SAME datum as the render bed hole (ofxP), fullview c_Of and the
// cammatch mouth gate. CN8_KERNEL.dep === CN8_F2.T === −CN8_R82.Y_N
// bit-exactly (asserted at load). Do not tweak independently of the kernel.
const CN8_KERNEL = (() => {
  const W_M = 0.085; // Joy official mouth (drawing W_M)
  return {
    W_M,
    R_N: 0.07219887303483237, // F2 nose fillet (= CN8_F2.RF, asserted below)
    fallR: 0.0525, // capture disc = the Ø105 mouth circle (drawing R)
    fallC: 0.0035, // O_f beyond both nose lines (drawing C)
    dep: 0.09015138956779158, // rail-end departure (= CN8_F2.T = −CN8_R82.Y_N, asserted below)
  };
})();

// circle-circle intersection (kernel circle_intersections twin)
function circInter(c1, r1, c2, r2) {
  const dx = c2[0] - c1[0], dy = c2[1] - c1[1];
  const d = Math.hypot(dx, dy);
  const a = (d * d + r1 * r1 - r2 * r2) / (2 * d);
  const h = Math.sqrt(Math.max(r1 * r1 - a * a, 0));
  const ux = dx / d, uy = dy / d;
  const fx = c1[0] + a * ux, fy = c1[1] + a * uy;
  return [[fx - h * uy, fy + h * ux], [fx + h * uy, fy - h * ux]];
}

/** Canonical CEBP corner jaw (kernel corner_canonical twin) in the local
 * frame u along the y-rail nose from the corner point, v along the x-rail
 * nose: arc1 tangent to the rail at (ut, 0), tangent arc2 on to the fall
 * circle. Angles traversed a1[0]→a1[1]→a2[1]. */
function cornerCanonical(s) {
  const ut = CEBP.cornerTangency * s;
  const r1 = CEBP.cornerR1 * s, r2 = CEBP.cornerR2 * s;
  const rf = CEBP.cornerFallR * s, cw = CEBP.cornerFallOff * s;
  const c1 = [ut, -r1];
  const thj = CEBP.cornerJunction;
  const c2 = [c1[0] - (r2 - r1) * Math.cos(thj), c1[1] - (r2 - r1) * Math.sin(thj)];
  const f = [-cw, -cw];
  const cands = circInter(c2, r2, f, rf);
  const x = cands[0][0] + cands[0][1] >= cands[1][0] + cands[1][1] ? cands[0] : cands[1];
  const thEnd = Math.atan2(x[1] - c2[1], x[0] - c2[0]);
  return { ut, c1, r1, a1: [Math.PI / 2, thj], c2, r2, a2: [thj, thEnd], x, f, rf };
}

/** Canonical CEBP middle jaw (kernel middle_canonical twin): the LOWER jaw
 * of the left middle pocket, local u along the pocket centre line (jaw at
 * u < 0), v behind the nose (< 0 behind). */
function middleCanonical(s) {
  const ut = CEBP.middleTangency * s;
  const r1 = CEBP.middleR1 * s, r2 = CEBP.middleR2 * s;
  const rf = CEBP.middleFallR * s, fd = CEBP.middleFallDepth * s;
  const c1 = [-ut, -r1];
  const thj = CEBP.middleJunction;
  const c2 = [c1[0] - (r2 - r1) * Math.cos(thj), c1[1] - (r2 - r1) * Math.sin(thj)];
  const f = [0, -fd];
  const cands = circInter(c2, r2, f, rf);
  const x = cands[0][1] >= cands[1][1] ? cands[0] : cands[1];
  const thEnd = Math.atan2(x[1] - c2[1], x[0] - c2[0]);
  return { ut, c1, r1, a1: [Math.PI / 2, thj], c2, r2, a2: [thj, thEnd], x, f, rf };
}

// ---- derived geometry context (mirrors Table::from_pocket_spec, table.rs) --
// (exported for tooling only — geometry checkers; app modules must not
// import it: OWNERSHIP cache-poison contract)
export function makeGeom(id) {
  const spec = specFor(id);
  const k = spec.kernel, r = spec.render;
  // pocketless carom branch (feature 012): mirrors Table::from_carom_spec —
  // 4 linear cushions with endpoints AT the four corner points, zero
  // pockets; no jaw/pocket-derived quantities exist.
  if (k.pocketless) {
    return {
      id, kernel: k, render: r,
      L: k.length, W: k.width, CW: k.cushionWidth,
      pockets: [],
    };
  }
  // curved-pocket (CEBP template) branch — catalog v7 Amendment A1: mirrors
  // Table::from_curved_pocket_spec. Rails end at the jaw tangency points,
  // jaws are the sampled tangent two-arc composites (railPolysTemplate),
  // pockets are the template FALL circles. The pool populate() consumes the
  // fall discs through the same kernel-field names it uses for the 9-ft
  // entries (cornerPocketRadius / sidePocketDepth / sidePocketRadius + cd),
  // filled in here from the template construction.
  if (k.template) {
    const L = k.length, W = k.width, CW = k.cushionWidth;
    const corner = cornerCanonical(k.cornerScale);
    const middle = middleCanonical(k.middleScale);
    const cfo = CEBP.cornerFallOff * k.cornerScale;
    // catalog v16 (calibration B1): the cn8Molded corner family mirrors
    // the kernel's R82 construction — rails end at the departure Y_N,
    // capture disc = the Ø105 mouth circle about the drawing O_f
    // (±(L/2 + C), ±(W/2 + C) — the bed-hole/cammatch datum). `cd`
    // deliberately stays cfo (the slate-edge datum the dressed template
    // consumers key on); the pocket centres carry the drawing C.
    const cn8 = k.cornerFamily === 'cn8Molded';
    const cRf = cn8 ? CN8_KERNEL.fallR : corner.rf;
    const cOff = cn8 ? CN8_KERNEL.fallC : cfo;
    const kk = {
      ...k,
      cornerPocketRadius: cRf,
      sidePocketRadius: middle.rf,
      sidePocketDepth: CEBP.middleFallDepth * k.middleScale,
    };
    return {
      id, kernel: kk, render: r, L, W, CW, transportRecipe: spec,
      template: true, corner, middle,
      utc: cn8 ? CN8_KERNEL.dep : corner.ut, utm: middle.ut, cd: cfo,
      pockets: [
        { x: -L / 2 - cOff, z: -W / 2 - cOff, r: cRf, corner: true },
        { x: 0, z: -W / 2 - kk.sidePocketDepth, r: middle.rf, corner: false },
        { x: L / 2 + cOff, z: -W / 2 - cOff, r: cRf, corner: true },
        { x: -L / 2 - cOff, z: W / 2 + cOff, r: cRf, corner: true },
        { x: 0, z: W / 2 + kk.sidePocketDepth, r: middle.rf, corner: false },
        { x: L / 2 + cOff, z: W / 2 + cOff, r: cRf, corner: true },
      ],
    };
  }
  const L = k.length, W = k.width, CW = k.cushionWidth;
  const ca = (k.cornerFacingDeviationDeg + 45.0) * Math.PI / 180.0;
  const sa = k.sideFacingDeviationDeg * Math.PI / 180.0;
  const dc = k.cornerJawRadius / Math.tan((Math.PI / 2 + ca) / 2);
  const ds = k.sideJawRadius / Math.tan((Math.PI / 2 + sa) / 2);
  // true-mouth inversion (table.rs from_pocket_spec): recovers the pooltool
  // widths bit-exactly for the default spec
  const pwc = k.cornerMouth / Math.SQRT2 - dc;
  const sw = k.sideMouth - 2.0 * ds;
  // side-jaw back-endpoint rise: pooltool cw·sin(sa) quirk (default) vs the
  // exact facing line cw·tan(sa) (measured entries) — table.rs `sjb`
  const sjb = k.exactSideFacing ? CW * Math.tan(sa) : CW * Math.sin(sa);
  const cd = k.cornerPocketDepth / Math.SQRT2;
  return {
    id, kernel: k, render: r, L, W, CW, ca, sa, dc, ds, pwc, sw, sjb, cd,
    cosCa: Math.cos(ca), sinCa: Math.sin(ca), tanCa: Math.tan(ca),
    cosSa: Math.cos(sa), sinSa: Math.sin(sa),
    // pockets, kernel order lb lc lt rb rc rt (three.js frame)
    pockets: [
      { x: -L / 2 - cd, z: -W / 2 - cd, r: k.cornerPocketRadius, corner: true },
      { x: 0, z: -W / 2 - k.sidePocketDepth, r: k.sidePocketRadius, corner: false },
      { x: L / 2 + cd, z: -W / 2 - cd, r: k.cornerPocketRadius, corner: true },
      { x: -L / 2 - cd, z: W / 2 + cd, r: k.cornerPocketRadius, corner: true },
      { x: 0, z: W / 2 + k.sidePocketDepth, r: k.sidePocketRadius, corner: false },
      { x: L / 2 + cd, z: W / 2 + cd, r: k.cornerPocketRadius, corner: true },
    ],
  };
}

const G0 = makeGeom(SCRIPTED_PIN_TABLE_ID); // kernel-DEFAULT mirror, NOT the app default

// public numbers (three.js frame: x = long axis toward foot, z = short axis).
// ALWAYS the DEFAULT entry's mirror — main.js's boot drift gate compares
// these against the kernel-DEFAULT engine.table() (its documented contract),
// and game.js's pocket-drop targeting tolerates the few-mm per-entry pocket
// offsets. Per-entry numbers live on TABLE_SPECS/makeGeom.
export const TABLE = {
  length: G0.L, width: G0.W, cushionWidth: G0.CW,
  noseHeight: (ballR) => 0.635 * 2 * ballR,
  pockets: G0.pockets,
  footSpot: { x: G0.L / 4, z: 0 },
  headSpot: { x: -G0.L / 4, z: 0 },
  frameWidth: 0.145,
  // cushion cloth-top plane above bed for the DEFAULT entry (K-66 profile:
  // WPA nose 0.635 × 0.05715 + K66.topRise = 0.04445 exactly; cuestick.js
  // lift-clearance consumer)
  railTop: 0.04445,
  frameTop: 0.047,  // wood rail top above bed
  bedAboveFloor: 0.79,
};
// ------------------------------------------------------------------ textures
// cloth albedo variation map (issue #228 rebuild). The pre-#228 map put
// ±5% luma (10% peak-to-peak) at ~4.3 cm and ±0.07 hue rotation (0.14
// full range) at ~9 cm (val(x*0.5) /
// val(x*0.23) fields): at device-class minification (phone 926x428 DPR3,
// LIVE) those low-frequency fields survive mipping as the owner's soft
// quilt/blotch patches — the A/B-proven dominant blotch source
// (the cloth-calibration record, internal; before/ablate-* frames). Real
