// leather binding, independent of the timber width. Retain the outer mount
// and physical mouth datums; the visible inner return has its own width.
const CN8_JOY_CORNER = Object.freeze({ bandWidth: 0.038, liningTop: 0.0347, woodChamfer: 0.035 });

function cn8JoyWoodCorner(K, sideInset = 0.0035, endInset = 0) {
  // The 07:50 overhead view shows a diagonal across the inner rail end.
  // Its 35 mm legs are a visual estimate; the outer leather butt stays put.
  const across = K.W_C - 0.0035 + sideInset;
  const along = K.Y_CUT - CN8_D2_SECTION.woodStop - endInset;
  return [[across, along - CN8_JOY_CORNER.woodChamfer],
    [across + CN8_JOY_CORNER.woodChamfer, along]];
}

function cn8D2PlanPair(K, station) {
  const a = Math.abs(station);
  let inner; let outer;
  if (a <= Math.PI / 4) {
    const angle = Math.PI / 4 - a;
    const d = [Math.cos(angle), Math.sin(angle)];
    inner = d.map((q) => K.C + K.R * q);
    outer = d.map((q) => K.C + (K.R + K.W_L) * q);
  } else {
    const t = Math.min(1, a - Math.PI / 4);
    const thetaS = Math.atan2(K.S[1] - K.C, K.S[0] - K.C);
    const betaS = Math.atan2(K.S[1] - K.O_B[1], K.S[0] - K.O_B[0]);
    const betaEnd = Math.atan2(K.Y_CUT - K.O_B[1], K.X_BC - K.O_B[0]);
    const firstLength = -thetaS * K.R;
    const secondLength = (betaEnd - betaS) * K.R_B;
    const distance = t * (firstLength + secondLength);
    if (distance <= firstLength) {
      const theta = -distance / K.R;
      inner = [K.C + K.R * Math.cos(theta), K.C + K.R * Math.sin(theta)];
    } else {
      const beta = betaS + (distance - firstLength) / K.R_B;
      inner = [K.O_B[0] + K.R_B * Math.cos(beta),
        K.O_B[1] + K.R_B * Math.sin(beta)];
    }
    outer = [K.A_R, K.C + (K.Y_CUT - K.C) * t];
  }
  if (station < 0) { inner.reverse(); outer.reverse(); }
  const lowerInner = inner;
  const dx = outer[0] - inner[0], dz = outer[1] - inner[1];
  const scale = CN8_JOY_CORNER.bandWidth / Math.hypot(dx, dz);
  inner = [outer[0] - dx * scale, outer[1] - dz * scale];
  return { inner, outer, lowerInner };
}

function cn8D2Section(width, station = 0) {
  // JOY Q8 visual revision: retain the measured plan and mating surfaces,
  // with a lighter rolled edge, shallower waist and shorter leather skirt.
  // These are EST proportions from the maintainer's new video references.
  const source = CN8_D2_SECTION;
  const depthScale = 0.104 / source.drop;
  const S = { ...source, radius: 0.006, gauge: 0.0026, drop: 0.104,
    body: source.body.map(([d, x]) => [d * depthScale, x * 0.60]),
    hemTransition: source.hemTransition * depthScale, amplitude: 0.0012 };
  // DERIVED: repeat the measured side-period on each analytic half-path.
  const radius = CN8_R82.R + CN8_R82.W_L;
  const arc = Math.PI * radius / 4;
  const limb = CN8_R82.C - CN8_R82.Y_CUT;
  const distance = Math.abs(cn8D3PathDistance(CN8_R82, station));
  const cycles = distance * S.lobes / (arc + limb);
  // TESSELLATION: weld phase endpoints affected only by floating arithmetic.
  const phase = Math.abs(cycles - Math.round(cycles)) < 1e-10 ? 0 : cycles - Math.floor(cycles);
  let at = 0;
  while (at + 2 < S.template.length && S.template[at + 1][0] < phase) at++;
  const aa = S.template[at]; const bb = S.template[at + 1];
  const relief = S.amplitude * (0.5 - 0.5 * Math.cos(2 * Math.PI * phase));
  const hemDepth = S.drop - S.amplitude + relief;
  const outer = []; const r = S.radius;
  const lip = cn8D3ReturnHeight(CN8_R82, station);
  // MODEL radius; sample count is TESSELLATION, never a physical dimension.
  const spans = S.sampling.roll_quarter_spans;
  for (let i = 0; i <= spans; i++) {
    const t = Math.PI - i * Math.PI / (2 * spans);
    // EST cross-model closure: the shared cloth-support plane clips only
    // the inner return. The circular portions retain the MODEL radius;
    // no neck, body or hem number is adjusted toward an unbound photo.
    outer.push([r + r * Math.cos(t), Math.max(lip, S.crownTop - r + r * Math.sin(t))]);
  }
  const shoulder = width - S.body[0][1];
  if (shoulder < 2 * r) throw new Error('Retained plan is too narrow for the measured roll');
  // DERIVED cross-model transfer: additional flat span = retained JOY
  // annulus minus the Star section width. Total flat span = width minus
  // the two measured roll radii and the source shoulder setback. The
  // Star terminal loft is retired; the unscaled central body continues
  // to the measured shared butt plane (D3 plan_span_mapping/terminal_fold).
  outer.push([shoulder - r, S.crownTop]);
  for (let i = 1; i <= spans; i++) {
    const t = Math.PI / 2 - i * Math.PI / (2 * spans);
    outer.push([shoulder - r + r * Math.cos(t), S.crownTop - r + r * Math.sin(t)]);
  }
  for (const [depth, setback] of S.body) {
    // EST ruled correspondence of the lowest source course only. MODEL
    // neck/body depths above the source anchor are not stretched to the hem.
    const t = Math.max(0, (depth - S.hemTransition) / (S.drop - S.hemTransition));
    outer.push([width - setback, S.crownTop - depth - t * (hemDepth - S.drop)]);
  }
  const cross = (a, b) => a[0] * b[1] - a[1] * b[0];
  const sub = (a, b) => [a[0] - b[0], a[1] - b[1]];
  const simplify = (p) => {
    if (p.length < 3) return p;
    const d = sub(p[p.length - 1], p[0]); const length = Math.hypot(...d);
    let max = 0; let at = 0;
    for (let i = 1; i + 1 < p.length; i++) {
      const error = Math.abs(cross(d, sub(p[i], p[0]))) / length;
      if (error > max) { max = error; at = i; }
    }
    // TESSELLATION: same 0.03 mm section chord budget as the measurement.
    if (max <= 0.00003) return [p[0], p[p.length - 1]];
    return [...simplify(p.slice(0, at + 1)).slice(0, -1), ...simplify(p.slice(at))];
  };
  const p = simplify(outer);
  const normals = p.slice(1).map((q, i) => {
    const d = sub(q, p[i]); const length = Math.hypot(...d);
    return [d[1] / length, -d[0] / length];
  });
  let inner = p.map((q, i) => {
    const a = normals[Math.max(0, i - 1)];
    const b = normals[Math.min(normals.length - 1, i)];
    const divisor = 1 + a[0] * b[0] + a[1] * b[1];
    return [q[0] + S.gauge * (a[0] + b[0]) / divisor,
      q[1] + S.gauge * (a[1] + b[1]) / divisor];
  });
  // A constant inward offset can overlap at a source facet shorter than
  // the transferred gauge. Trim those offset loops at their exact line
  // intersections; never shrink the visible measured surface to hide one.
  let repaired = true;
  while (repaired) {
    repaired = false;
    for (let i = 0; i + 1 < inner.length && !repaired; i++) {
      for (let j = i + 2; j + 1 < inner.length; j++) {
        const d = sub(inner[i + 1], inner[i]);
        const e = sub(inner[j + 1], inner[j]);
        const den = cross(d, e);
        if (Math.abs(den) < 1e-14) continue; // TESSELLATION numeric zero.
        const delta = sub(inner[j], inner[i]);
        const u = cross(delta, e) / den; const v = cross(delta, d) / den;
        if (u > 0 && u < 1 && v > 0 && v < 1) {
          const hit = [inner[i][0] + d[0] * u, inner[i][1] + d[1] * u];
          inner = [...inner.slice(0, i + 1), hit, ...inner.slice(j + 1)];
          repaired = true;
          break;
        }
      }
    }
  }
  // DERIVED planar cut at the measured varying hem; do not retain an
  // offset end below the source exterior edge.
  const hemY = outer[outer.length - 1][1];
  for (let i = 0; i + 1 < inner.length; i++) {
    if (inner[i][1] >= hemY && inner[i + 1][1] < hemY) {
      const t = (hemY - inner[i][1]) / (inner[i + 1][1] - inner[i][1]);
      inner = [...inner.slice(0, i + 1), [inner[i][0] + (inner[i + 1][0] - inner[i][0]) * t, hemY]];
      break;
    }
  }
  // TESSELLATION: fixed inner-course samples permit a closed loft across
  // offset-loop topology changes. The seal measures the resulting chord
  // error and wall gauge; this count is not a manufacturing measurement.
  const INNER_SAMPLES = S.sampling.inner_profile_samples;
  const length = [0];
  for (let i = 1; i < inner.length; i++) {
    length.push(length[i - 1] + Math.hypot(...sub(inner[i], inner[i - 1])));
  }
  const slots = [];
  for (let i = 0; i < inner.length; i++) {
    const ideal = Math.round(length[i] / length[length.length - 1] * (INNER_SAMPLES - 1));
    slots.push(Math.max(i ? slots[i - 1] + 1 : 0,
      Math.min(INNER_SAMPLES - inner.length + i, ideal)));
  }
  const sampled = [];
  for (let i = 0, k = 0; i < INNER_SAMPLES; i++) {
    while (k + 2 < slots.length && slots[k + 1] < i) k++;
    const t = (i - slots[k]) / (slots[k + 1] - slots[k]);
    sampled.push(inner[k].map((q, axis) => q + (inner[k + 1][axis] - q) * t));
  }
  return { profile: [...outer, ...sampled.reverse()], outer, inner, sampled };
}

function cn8D3PathDistance(K, station) {
  // DERIVED signed outer-path arclength, shared by hem placement and grain.
  // Arc stations are radians; limb stations are normalized linear progress.
  const radius = K.R + K.W_L;
  const arc = Math.PI * radius / 4;
  const limb = K.C - K.Y_CUT;
  const a = Math.abs(station);
  const distance = a <= Math.PI / 4 ? a * radius : arc + (a - Math.PI / 4) * limb;
  return Math.sign(station) * distance;
}

function cn8D2Stations() {
  const K = CN8_R82; const S = CN8_D2_SECTION;
  const radius = K.R + K.W_L; const arc = Math.PI * radius / 4;
  const limb = K.C - K.Y_CUT; const points = [];
  const n = S.sampling.limb_spans; const m = S.sampling.arc_spans;
  for (let i = 0; i < n; i++) points.push(-Math.PI / 4 - 1 + i / n);
  for (let i = 0; i <= m; i++) points.push(-Math.PI / 4 + Math.PI * i / (2 * m));
  for (let i = 1; i <= n; i++) points.push(Math.PI / 4 + i / n);
  // Every measured hem knot is a mandatory loft station. No analytic wave.
  for (let cycle = 0; cycle < S.lobes; cycle++) {
    for (const [phase] of S.template) {
      const distance = (cycle + phase) * (arc + limb) / S.lobes;
      const t = distance <= arc ? distance / radius : Math.PI / 4 + (distance - arc) / limb;
      points.push(-t, t);
    }
  }
  // Both skins use the same contact chords. These are additional sampling
  // stations on the held analytic plan, not a changed pocket boundary.
  for (const station of cn8D3MatingMap(K).stations.values()) points.push(-station, station);
  points.push(-cn8D3MatingMap(K).first, cn8D3MatingMap(K).first);
  // TESSELLATION station weld prevents duplicate zero-area strips.
  return [...new Map(points.map((p) => [p.toFixed(S.sampling.numeric_station_weld_digits), p])).values()]
    .sort((a, b) => a - b);
}

function cn8D2BedEdge(K) {
  // DERIVED cloth/support termination: at bed y=0 the hidden outer edge
  // ends on the INNER face of the measured cover. The previous straight
  // chamfer/box outline pierced the Star terminal waist. This changes only
  // cloth outside the playfield; the mouth holes and jaw-foot chain stay.
  const edge = cn8D2Stations().map((station) => {
    const pair = cn8D2PlanPair(K, station);
    const d = [pair.outer[0] - pair.inner[0], pair.outer[1] - pair.inner[1]];
    const width = Math.hypot(...d);
    const inner = cn8D2Section(width, station).inner;
    let radial = -Infinity;
    for (let j = 0; j + 1 < inner.length; j++) {
      const a = inner[j]; const b = inner[j + 1];
      if (a[1] * b[1] > 0 || a[1] === b[1]) continue;
      const t = -a[1] / (b[1] - a[1]);
      radial = Math.max(radial, a[0] + (b[0] - a[0]) * t);
    }
    if (!Number.isFinite(radial)) throw new Error('Measured cover does not cross the bed datum');
    return [pair.inner[0] + d[0] * radial / width,
      pair.inner[1] + d[1] * radial / width];
  });
  // The almost straight limb varies below the Float32 position precision.
  // Triangulating every loft knot there creates disconnected sliver faces.
  // Simplify the hidden bed outline before triangulation, within 1 micron;
  // the visible leather, mouth and jaw-foot boundaries retain their samples.
  const simplify = (points) => {
    if (points.length < 3) return points;
    const a = points[0], b = points.at(-1), dx = b[0] - a[0], dz = b[1] - a[1];
    const length = Math.hypot(dx, dz);
    let error = 0, at = 0;
    for (let i = 1; i + 1 < points.length; i++) {
      const distance = Math.abs(dx * (points[i][1] - a[1]) - dz * (points[i][0] - a[0])) / length;
      if (distance > error) { error = distance; at = i; }
    }
    if (error <= 0.000001) return [a, b];
    return [...simplify(points.slice(0, at + 1)).slice(0, -1), ...simplify(points.slice(at))];
  };
  return simplify(edge);
}

function cn8D2CornerGeometry(K, L, W, sx, sz) {
  const S = CN8_D2_SECTION;
  const stations = cn8D2Stations();
  const pos = []; const uv = []; const capUV = []; const idx = []; const sections = [];
  let count = 0;
  for (const station of stations) {
    const pair = cn8D2PlanPair(K, station);
    const dx = pair.outer[0] - pair.inner[0];
    const dz = pair.outer[1] - pair.inner[1]; const width = Math.hypot(dx, dz);
    const section = cn8D2Section(width, station);
    const pathDistance = cn8D3PathDistance(K, station);
    count = section.profile.length;
    sections.push({ station, width, ...pair, profile: section.profile });
    let distance = 0;
    for (let i = 0; i < count; i++) {
      const [radial, y] = section.profile[i];
      const fraction = radial / width;
      pos.push(sx * (L / 2 + pair.inner[0] + dx * fraction), y,
        sz * (W / 2 + pair.inner[1] + dz * fraction));
      if (i) distance += Math.hypot(radial - section.profile[i - 1][0],
        y - section.profile[i - 1][1]);
      // EST inherited procedural-grain repeat; one physical period on arc
      // and limbs. The tagged repeat is unchanged; no photo texture is used.
      uv.push(pathDistance / S.grainRepeat, distance / S.grainRepeat);
      // DERIVED cap-plane coordinates, orthonormal radial distance / height.
      // MODEL(Star) terminal faces carry Leather with nondegenerate UVs;
      // retain the same EST repeat. UV1 is consumed only by the cap groups.
      capUV.push(radial / S.grainRepeat, y / S.grainRepeat);
    }
  }
  for (let i = 0; i + 1 < stations.length; i++) {
    for (let j = 0; j < count; j++) {
      const k = (j + 1) % count;
      const a = i * count + j; const b = (i + 1) * count + j;
      const c = i * count + k; const d = (i + 1) * count + k;
      idx.push(a, b, c, c, b, d);
    }
  }
  const skinIndexCount = idx.length;
  const capGroups = [];
  for (const end of [0, stations.length - 1]) {
    const start = idx.length;
    const contour = sections[end].profile.map(([r, h]) => new THREE.Vector2(r, h));
    // Triangulate the corner vertices first, then restore EVERY boundary
    // subdivision by splitting its incident triangle. Feeding all uniform
    // collinear samples straight to earcut creates zero-area ears after
    // Float32 publication; dropping those ears would open a topological seam.
    const keep = contour.map((_, i) => i);
    let changed = true;
    while (changed && keep.length > 3) {
      changed = false;
      for (let j = 0; j < keep.length; j++) {
        const a = contour[keep[(j + keep.length - 1) % keep.length]];
        const b = contour[keep[j]]; const c = contour[keep[(j + 1) % keep.length]];
        const d = c.clone().sub(a); const q = b.clone().sub(a);
        const t = q.dot(d) / d.lengthSq();
        // TESSELLATION only: 0.0001 mm, below the Float32 frame allowance.
        if (t > 0 && t < 1 && Math.abs(d.x * q.y - d.y * q.x) / d.length() < 1e-7) {
          keep.splice(j, 1); changed = true; break;
        }
      }
    }
    const split = new Map();
    for (let j = 0; j < keep.length; j++) {
      const a = keep[j]; const b = keep[(j + 1) % keep.length];
      const row = [a];
      for (let k = (a + 1) % count; k !== b; k = (k + 1) % count) row.push(k);
      row.push(b);
      if (row.length > 2) {
        split.set(`${a},${b}`, row); split.set(`${b},${a}`, [...row].reverse());
      }
    }
    const pending = THREE.ShapeUtils.triangulateShape(keep.map((j) => contour[j]), [])
      .map((tri) => tri.map((j) => keep[j]));
    const triangles = [];
    while (pending.length) {
      const tri = pending.pop(); let divided = false;
      for (let j = 0; j < 3; j++) {
        const row = split.get(`${tri[j]},${tri[(j + 1) % 3]}`);
        if (!row) continue;
        const opposite = tri[(j + 2) % 3];
        for (let k = 0; k + 1 < row.length; k++) pending.push([row[k], row[k + 1], opposite]);
        divided = true; break;
      }
      if (!divided) triangles.push(tri);
    }
    for (const tri of triangles) {
      // Both cut sections are closed with the same measured profile.
      const [a, b, c] = tri.map((j) => end * count + j);
      if (end === 0) idx.push(a, c, b); else idx.push(a, b, c);
    }
    capGroups.push({ end: end === 0 ? 'start' : 'finish', start, count: idx.length - start, materialIndex: 1 });
  }
  // Choose the outward winding once after the table-quadrant reflection.
  // The end-cap winding is independently checked in the seal edge census.
  let volume = 0;
  const origin = [sx * L / 2, 0, sz * W / 2];
  for (let i = 0; i < idx.length; i += 3) {
    const v = idx.slice(i, i + 3).map((j) => pos.slice(j * 3, j * 3 + 3)
      .map((q, k) => q - origin[k]));
    volume += v[0][0] * (v[1][1] * v[2][2] - v[1][2] * v[2][1])
      + v[0][1] * (v[1][2] * v[2][0] - v[1][0] * v[2][2])
      + v[0][2] * (v[1][0] * v[2][1] - v[1][1] * v[2][0]);
  }
  if (volume < 0) for (let i = 0; i < idx.length; i += 3) [idx[i + 1], idx[i + 2]] = [idx[i + 2], idx[i + 1]];
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  geometry.setAttribute('uv1', new THREE.Float32BufferAttribute(capUV, 2));
  geometry.setIndex(idx);
  geometry.addGroup(0, skinIndexCount, 0);
  for (const cap of capGroups) geometry.addGroup(cap.start, cap.count, cap.materialIndex);
  // TESSELLATION: angle weighting makes smooth normals independent of the
  // irregular measurement-station spacing. It changes no position or albedo.
  const normals = new Float64Array(pos.length);
  for (let i = 0; i < idx.length; i += 3) {
    const ids = idx.slice(i, i + 3);
    const points = ids.map((j) => new THREE.Vector3().fromArray(pos, j * 3));
    const face = points[1].clone().sub(points[0]).cross(points[2].clone().sub(points[0])).normalize();
    for (let j = 0; j < 3; j++) {
      const a = points[(j + 1) % 3].clone().sub(points[j]);
      const b = points[(j + 2) % 3].clone().sub(points[j]);
      const weight = Math.atan2(a.clone().cross(b).length(), a.dot(b));
      for (let axis = 0; axis < 3; axis++) normals[ids[j] * 3 + axis] += face.getComponent(axis) * weight;
    }
  }
  for (let i = 0; i < normals.length; i += 3) {
    const length = Math.hypot(normals[i], normals[i + 1], normals[i + 2]);
    for (let axis = 0; axis < 3; axis++) normals[i + axis] /= length;
  }
  geometry.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
  geometry.userData.cn8D3 = { schema: 'ob-cn8-d3-loft/1',
    source: 'Retained outer mount and physical mouth; independent JOY binding width, roll, gauge, waist, drop and hem (EST)',
    bandWidth: CN8_JOY_CORNER.bandWidth,
    visualRevision: 'docs/geometry/cn8-joy-furniture-revision.md',
    definition: 'docs/geometry/cn8-pocket-d3-section.json',
    definitionSha256: CN8_D2_SECTION.definitionSha256,
    stationCount: stations.length, profileCount: count,
    outerProfileCount: count - CN8_D2_SECTION.sampling.inner_profile_samples, stations,
    capUV: { channel: 1, repeat: S.grainRepeat, groups: capGroups,
      source: 'docs/geometry/cn8-pocket-d3-star-caps.json',
      mapping: 'DERIVED orthonormal radial/height plane; retained EST repeat; MODEL(Star) textured end-face assignment' } };
  return geometry;
}

function cn8D3CapMaterial(cover) {
  // A second UV channel avoids splitting or changing the sealed solid's
  // position/index/normal buffers. Only the terminal draw groups use it.
  const material = cover.clone();
  material.name = cover.name + '-endcap';
  const textures = new Map();
  for (const key of ['map', 'normalMap', 'roughnessMap', 'bumpMap', 'emissiveMap']) {
    const source = cover[key];
    if (!source) continue;
    if (!textures.has(source)) {
      const texture = source.clone();
      texture.channel = 1;
      texture.needsUpdate = true;
      textures.set(source, texture);
    }
    material[key] = textures.get(source);
  }
  material.onBeforeCompile = cover.onBeforeCompile;
  material.customProgramCacheKey = cover.customProgramCacheKey;
  return material;
}


// ORDER-8: cloth and inner return share one analytic boundary. The source
// supplies the upper-plane cloth recess; adapting its separated end ridge
// to the held CN8 mouth is EST (see tongue_return_mapping). In particular,
// a source gap or the retired positive lap is never a zero-gap measurement.
const cn8D3MatingCache = new WeakMap();
function cn8D3MatingMap(K) {
  if (cn8D3MatingCache.has(K)) return cn8D3MatingCache.get(K);
  const { chain, chainN } = cn8MouthOccGeom();
  const cross = (a, b) => a[0] * b[1] - a[1] * b[0];
  const interp = (array, row) => {
    const i = Math.min(array.length - 2, Math.floor(row)); const t = row - i;
    return array[i].map((v, j) => v + (array[i + 1][j] - v) * t);
  };
  const last = Math.PI / 4 + 1;
  const rounds = CN8_D2_SECTION.sampling.mating_root_iterations;
  // Intersect the terminal crest normal with the new inner return. The
  // cloth now has a real span here; pinching it to the old rim left a gap.
  const terminal = chain.at(-1), terminalNormal = chainN.at(-1);
  const sideAt = (station) => cross(cn8D2PlanPair(K, station).inner
    .map((v, j) => v - terminal[j]), terminalNormal);
  let firstLo = 0, firstHi = last;
  for (let i = 0; i < rounds; i++) {
    const mid = (firstLo + firstHi) / 2;
    if (sideAt(firstLo) * sideAt(mid) <= 0) firstHi = mid; else firstLo = mid;
  }
  const first = (firstLo + firstHi) / 2;
  const at = (station) => {
    if (station < first - 1e-12 || station > last + 1e-12) return null;
    const point = cn8D2PlanPair(K, station).inner;
    if (Math.abs(station - first) < 1e-12) {
      const span = (point[0] - terminal[0]) * terminalNormal[0]
        + (point[1] - terminal[1]) * terminalNormal[1];
      return { row: chain.length - 1, c: terminal, n: terminalNormal, span, station, point };
    }
    for (let i = 0; i + 1 < chain.length; i++) {
      const side = (u) => {
        const c = interp(chain, i + u), n = interp(chainN, i + u);
        return cross(point.map((v, j) => v - c[j]), n);
      };
      if (side(0) * side(1) > 0) continue;
      let lo = 0, hi = 1;
      for (let j = 0; j < rounds; j++) {
        const mid = (lo + hi) / 2;
        if (side(lo) * side(mid) <= 0) hi = mid; else lo = mid;
      }
      const row = i + (lo + hi) / 2, c = interp(chain, row), n = interp(chainN, row);
      const norm = Math.hypot(...n); n[0] /= norm; n[1] /= norm;
      const span = (point[0] - c[0]) * n[0] + (point[1] - c[1]) * n[1];
      // TESSELLATION: tolerate only numerical zero at the terminal weld.
      if (span >= -1e-12) return { row, c, n, span: Math.max(0, span), station, point };
    }
    throw new Error(`CN8 shared mating boundary has no cloth row at ${station}`);
  };
  const end = at(last), stations = new Map([[chain.length - 1, first]]);
  for (let row = Math.ceil(end.row); row + 1 < chain.length; row++) {
    let lo = first, hi = last;
    for (let j = 0; j < rounds; j++) {
      const mid = (lo + hi) / 2;
      if (at(mid).row > row) lo = mid; else hi = mid;
    }
    stations.set(row, (lo + hi) / 2);
  }
  const result = { at, first, last, stations, chain, chainN, interp, end };
  cn8D3MatingCache.set(K, result);
  return result;
}

function cn8D3TongueProfile(K, row, span) {
  const S = CN8_D2_SECTION, p = S.tongueSupport;
  const fraction = Math.min(1, row / S.sampling.tongue_roll_rows);
  const t = fraction * fraction * (3 - 2 * fraction);
  const profile = p.deep_mm.map(([x, y], i) => [
    (x + (p.wall_mm[i][0] - x) * t) / 1000,
    i ? Math.min(S.crownTop - S.clothRecess, (y + (p.wall_mm[i][1] - y) * t) / 1000) : K.H_NOSE]);
  const scale = Math.min(1, span / (profile[4][0] + (p.lap_mm + p.profile_padding_mm) / 1000));
  const base = profile.map(([x, y]) => [x * scale,
    K.H_NOSE + (y - K.H_NOSE) * Math.min(1, scale * p.height_gain)]);
  return { base, scale };
}

function cn8D3ReturnHeight(K, station) {
  const contact = cn8D3MatingMap(K).at(Math.abs(station));
  const support = contact ? cn8D3TongueProfile(K, contact.row, contact.span).base[4][1] : K.H_NOSE;
  return Math.min(CN8_D2_SECTION.crownTop, support + CN8_D2_SECTION.clothRecess);
}

function cn8D3TongueRows(K) {
  const map = cn8D3MatingMap(K), rows = new Map();
  for (let row = 0; row < map.chain.length; row++) {
    const station = map.stations.get(row);
    rows.set(row.toFixed(12), station === undefined
      ? { row, c: map.chain[row], n: map.chainN[row], station: null }
      : { ...map.at(station), row });
  }
  for (const station of cn8D2Stations()) {
    if (station < map.first) continue;
    const contact = map.at(station);
    rows.set(contact.row.toFixed(12), contact);
  }
  // A row at each chamfer endpoint keeps the cloth boundary on both
  // straight wood edges instead of bridging across the change of direction.
  for (const point of cn8JoyWoodCorner(K)) {
    const cross = (row) => {
      const c = map.interp(map.chain, row), n = map.interp(map.chainN, row);
      return (point[0] - c[0]) * n[1] - (point[1] - c[1]) * n[0];
    };
    for (let i = 0; i + 1 < map.chain.length; i++) {
      if (cross(i) * cross(i + 1) > 0) continue;
      let lo = i, hi = i + 1;
      for (let j = 0; j < 52; j++) {
        const mid = (lo + hi) / 2;
        if (cross(lo) * cross(mid) > 0) lo = mid; else hi = mid;
      }
      const row = (lo + hi) / 2;
      if (row >= map.end.row) continue;
      const c = map.interp(map.chain, row), n = map.interp(map.chainN, row);
      const norm = Math.hypot(...n); n[0] /= norm; n[1] /= norm;
      if ((point[0] - c[0]) * n[0] + (point[1] - c[1]) * n[1] <= 0) continue;
      rows.set(row.toFixed(12), { row, c, n, station: null });
      break;
    }
  }
  return [...rows.values()].sort((a, b) => a.row - b.row);
}

function cn8D3CoverRayTree(geometry, openOrigin = false, contactDistance = 0) {
  // DERIVED acceleration over emitted triangles. Bounds are only an index;
  // no replacement volume, clearance or simplified profile is introduced.
  // Leaf size is a CPU subdivision choice, not a geometric allowance.
  const positions = geometry.attributes.position.array, index = geometry.index.array;
  const bounds = [], centres = [];
  for (let i = 0; i < index.length; i += 3) {
    const box = new THREE.Box3();
    for (let j = 0; j < 3; j++) box.expandByPoint(new THREE.Vector3().fromArray(positions, index[i + j] * 3));
    bounds.push(box); centres.push(box.getCenter(new THREE.Vector3()));
  }
  const build = (triangles) => {
    const box = new THREE.Box3();
    for (const triangle of triangles) box.union(bounds[triangle]);
    if (triangles.length <= 16) return { box, triangles };
    const size = box.getSize(new THREE.Vector3());
    const axis = size.x >= size.y && size.x >= size.z ? 'x' : size.y >= size.z ? 'y' : 'z';
    triangles.sort((a, b) => centres[a][axis] - centres[b][axis]);
    const middle = Math.floor(triangles.length / 2);
    return { box, left: build(triangles.slice(0, middle)), right: build(triangles.slice(middle)) };
  };
  const root = build(bounds.map((_, i) => i));
  const ray = new THREE.Ray(), hit = new THREE.Vector3();
  const a = new THREE.Vector3(), b = new THREE.Vector3(), c = new THREE.Vector3();
  const blocked = (node) => {
    if (!ray.intersectBox(node.box, hit)) return false;
    if (!node.triangles) return blocked(node.left) || blocked(node.right);
    for (const triangle of node.triangles) {
      a.fromArray(positions, index[triangle * 3] * 3);
      b.fromArray(positions, index[triangle * 3 + 1] * 3);
      c.fromArray(positions, index[triangle * 3 + 2] * 3);
      // The emitting surface is the ray's open endpoint. Exact incident
      // vertices are excluded by topology, not by a distance epsilon. This
      // also avoids a rounded positive t for a mathematically incident face.
      if (openOrigin && (a.equals(ray.origin) || b.equals(ray.origin) || c.equals(ray.origin))) continue;
      if (ray.intersectTriangle(a, b, c, false, hit)
        && (!openOrigin || !hit.equals(ray.origin))
        && hit.distanceTo(ray.origin) >= contactDistance) return true;
    }
    return false;
  };
  return (x, y, z, dx, dy, dz) => {
    ray.origin.set(x, y, z); ray.direction.set(dx, dy, dz);
    return blocked(root);
  };
}

function cn8D3SolidRayTree(group, contactDistance = 0) {
  // ORDER-12 O2: snapshot the completed table's actual opaque draws. The
  // Float64 world coordinates preserve each published Float32 vertex and
  // its mesh transform; they do not resample or reshape any solid. Alpha
  // shader holes are outside the CPU triangle-intersection instrument.
  group.updateMatrixWorld(true);
  const inverseRoot = group.matrixWorld.clone().invert();
  const positions = [], indices = [], members = [];
  const point = new THREE.Vector3(), matrix = new THREE.Matrix4();
  let ordinal = 0;
  const visit = (object, visible, path) => {
    visible = visible && object.visible;
    if (object.isMesh) {
      const id = ordinal++;
      if (visible) {
        if (object.isInstancedMesh || object.isSkinnedMesh) {
          throw new Error('CN8 solid census requires explicit instance/skinning expansion');
        }
        const geometry = object.geometry, attribute = geometry.getAttribute('position');
        const materials = Array.isArray(object.material) ? object.material : [object.material];
        const index = geometry.index, total = index ? index.count : attribute.count;
        const drawStart = geometry.drawRange.start;
        const drawEnd = Math.min(total, drawStart + geometry.drawRange.count);
        const ranges = Array.isArray(object.material) ? geometry.groups
          : [{ start: 0, count: total, materialIndex: 0 }];
        const selected = [];
        for (const range of ranges) {
          const material = materials[range.materialIndex];
          if (!material?.visible || material.transparent || material.opacity !== 1) continue;
          const start = Math.max(drawStart, range.start);
          const end = Math.min(drawEnd, range.start + range.count);
          for (let i = start; i + 2 < end; i += 3) {
            selected.push(index ? index.getX(i) : i, index ? index.getX(i + 1) : i + 1,
              index ? index.getX(i + 2) : i + 2);
          }
        }
        if (selected.length) {
          const base = positions.length / 3, start = indices.length / 3;
          matrix.multiplyMatrices(inverseRoot, object.matrixWorld);
          for (let i = 0; i < attribute.count; i++) {
            point.fromBufferAttribute(attribute, i).applyMatrix4(matrix);
            positions.push(point.x, point.y, point.z);
          }
          for (const vertex of selected) indices.push(base + vertex);
          members.push({ ordinal: id, name: object.name || '(unnamed)', path,
            triangleStart: start, triangles: selected.length / 3, vertices: attribute.count,
            source: 'Completed table mesh position/index/draw-range/material/transform definitions' });
        }
      }
    }
    object.children.forEach((child, i) => visit(child, visible, `${path}/${i}`));
  };
  visit(group, true, 'table');
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(new Float64Array(positions), 3));
  geometry.setIndex(indices);
  // O3's offline caller derives this distance from the published Float32
  // solid set. Zero is the archived no-contact-classification red arm.
  if (!Number.isFinite(contactDistance) || contactDistance < 0) throw new Error('Invalid derived contact distance');
  const blocked = cn8D3CoverRayTree(geometry, true, contactDistance);
  return { blocked, members, geometry,
    rayOpenM(_toM, x, y, z, dx, dy, dz) { return !blocked(x, y, z, dx, dy, dz); } };
}

// GH-1080 D2b (owner card 41: corner F2, signed incl. §6): the corner jaw is
// the F2 family — nose line → fillet R_f from the departure t → straight
// throat wall widening θ per side (it never converges) → the Ø105 mouth
// circle. Primary parameters are the clamp-free calibrated photo fit (astra
// D2a R3 F2_fixed85, pooled, 0 px). The wall-to-ring connection is the A1
// fill from the purchased snooker models: Star ends its jaw at the leather
// cup in a SHARP junction (29–35° kink, no positive tangent blend; Magnum's
// rim and toe stay separate), so R_b = 0 — the wall runs straight on to the
// circle and meets it in a 34.15° kink (ruling 2026-10-12; a radius would be
// an invented dimension). The blend construction stays general (R_b > 0
// gives the internally tangent concave blend). Every other corner letter is
// derived here, once, for the renderer (CN8_R82) and the kernel twin
// (CN8_KERNEL).
const CN8_F2 = (() => {
  const T = 0.09015138956779158; // PHOTO: departure from the nose-line corner N
  const RF = 0.07219887303483237; // PHOTO: nose fillet radius
  const TH = 3.410678706496409 * Math.PI / 180; // PHOTO: wall opening per side
  const RB = 0; // MODEL(Star): sharp wall-to-ring junction (A1 fill; see above)
  const C = 0.0035, R = 0.0525; // RETAINED: O_f = (C, C), the Ø105 mouth circle
  // drawing frame (CN8_R82): x behind this rail's nose line, y along it
  // (negative away from the corner); astra's (u, v) maps to (−v, −u).
  const a = Math.PI * 0.75 + TH;
  const n = [Math.cos(a), Math.sin(a)], d = [-Math.sin(a), Math.cos(a)];
  const c = [T, -RF], tw = [c[0] + RF * n[0], c[1] + RF * n[1]];
  const v = [tw[0] + RB * n[0] + C, tw[1] + RB * n[1] + C];
  const vn = v[0] * n[0] + v[1] * n[1], vd = v[0] * d[0] + v[1] * d[1];
  const len = -vd + Math.sqrt((R - RB) ** 2 - vn * vn);
  const fw = [tw[0] + len * d[0], tw[1] + len * d[1]];
  const cb = [fw[0] + RB * n[0], fw[1] + RB * n[1]];
  const k = R / (R - RB), end = [-C + k * (cb[0] + C), -C + k * (cb[1] + C)];
  // fillet circle ∩ mouth circle on the drawn fillet arc (the kernel's
  // roll∩circle station X_N of the retired R45 family)
  const dx = -C - c[0], dy = -C - c[1], D = Math.hypot(dx, dy);
  const p = (D * D + RF * RF - R * R) / (2 * D), h = Math.sqrt(RF * RF - p * p);
  const fx = c[0] + p * dx / D, fy = c[1] + p * dy / D;
  const xn = [[fx - h * dy / D, fy + h * dx / D], [fx + h * dy / D, fy - h * dx / D]]
    .find((q) => {
      const ang = Math.atan2(q[1] - c[1], q[0] - c[0]);
      return ang >= Math.PI / 2 - 1e-12 && ang <= a + 1e-12;
    });
  const M = ([u, w]) => [-w, -u];
  const psi = ([x, y]) => 45 - Math.atan2(y - C, x - C) * 180 / Math.PI;
  const twD = M(tw), fwD = M(fw);
  const wl = Math.hypot(fwD[0] - twD[0], fwD[1] - twD[1]);
  const wd = [(fwD[0] - twD[0]) / wl, (fwD[1] - twD[1]) / wl];
  return {
    T, RF, TH, RB,
    O_N: M(c), T_W: twD, F_W: fwD, E_C: M(cb), F_C: M(end), X_N: M(xn),
    WALL_D: wd, WALL_N: [wd[1], -wd[0]], // unit direction; normal away from the void
    PSI_F: psi(M(end)), PSI_B: psi(M(xn)),
  };
})();

