// Dev gate: every kernel linear cushion segment endpoint must coincide with a
// vertex of the visual rail polygons (visual jaw chords collinear with kernel
// jaw segments). Called from the app's kernel-mirror drift check with
// engine.table() (kernel-DEFAULT geometry — main.js's documented contract);
// per-entry callers (tests/tools) pass the entry's table id explicitly.
// Returns human-readable drift strings (empty = aligned).
export function checkRailKernelAlignment(kt, tableId = SCRIPTED_PIN_TABLE_ID) {
  const G = makeGeom(tableId);
  const verts = railPolysFor(G).flat()
    .map(([kx, ky]) => [kx - G.W / 2, ky - G.L / 2]);
  const drift = [];
  kt.linear.forEach((s, i) => {
    for (const p of [s.p1, s.p2]) {
      let d = Infinity;
      for (const [x, y] of verts) d = Math.min(d, Math.hypot(x - p.x, y - p.y));
      if (!(d <= 1e-9)) {
        drift.push(`kernel linear[${i}] endpoint (${p.x}, ${p.y}) is ${d} from the nearest visual rail vertex`);
      }
    }
  });
  return drift;
}

