const ROX_CAP_TOP = [[47.9, 41.041], [52.9, 41.271], [57.9, 41.593], [62.9, 41.923], [67.9, 42.235], [72.9, 42.51], [77.9, 42.762], [82.9, 42.953], [87.9, 43.074], [92.9, 43.138], [97.9, 43.08], [102.9, 42.964], [107.9, 42.766], [112.9, 42.474], [117.9, 42.147], [122.9, 41.765], [127.9, 41.355], [132.9, 40.925], [137.9, 40.466], [142.9, 40.002], [147.9, 39.534], [152.9, 39.071], [156.1, 38.73], [157.9, 38.035], [158.9, 36.83]]; // RB-04 top_profile_du_z_long_x600_every5mm (u from the nose, z above the bed, mm, raw)
const ROX_CAP_INNER_U = 47.83; // RB-04 inner_edge du long 47.83 (0.242 inside the cushion back, as the model)
const ROX_CAP_TOP_Z_INNER = 41.041; // RB-04 cap_top_at_inner_edge_z long
