const ROX_SPANDREL = { yFaces: [525.17, 555.17], thick: 30.0, topGap: 6.75 }; // RC-20 y_faces_abs / thickness / top_gap_below_body_underside (model raw, C18)
const ROX_SPANDREL_ARC = { crownZ: 473.9, R: 2358.3 }; // RC-14 crown_z_floor_datum / soffit_circle_fit_det04_x0_constrained R (product photo)
const ROX_PAD_TO_BOW = 62.085; // RC-21 bow_foot_mid_minus_pad_centroid (model raw)
