const ROX_CUP_WALL = 1.07; // CP-12 wall_thickness value (SP-12 wall_thickness 1.07; CP-15c flange thickness 1.07)
const ROX_CUP_OPEN_Z = -24.0; // CP-12 open_C_to_closed_bucket_transition open_at
