const ROX_CUP_SPAN = 114.9; // CP-12 angular_span inner_wall_phi_at_z_bed+20 −114.8 / +115.0 (symmetrised)
const ROX_CUP_DRAIN_R = { corner: 9.15, side: 9.49 }; // CP-12 drain_hole R_mm / SP-12 drain R
const ROX_CORNER_RIM = [[0, 46.62], [15, 46.57], [30, 45.9], [45, 44.78], [60, 43.29], [75, 42.86], [90, 42.7], [105, 42.48], [120, 42.36]]; // CP-12 rim_height per_15deg_bin, ± bins averaged (phi from the outward diagonal)
const ROX_CORNER_HS = [[-135, 72.4], [-120, 70.9], [-105, 58.6], [-90, 57.5], [-75, 60.1], [-60, 63.1], [-45, 66.9], [-30, 69.3], [-15, 70.3], [0, 69.8], [15, 69.3], [30, 66.3], [45, 63.4], [60, 59.6], [75, 58.0], [90, 59.1], [105, 71.3], [120, 72.2]]; // CP-15 inner_horseshoe r_of_phi_deg at bed+41 (+phi = long-rail side, CP-12 v_sign)
const ROX_CORNER_FLANGE = [[44.26, 46.62], [45.29, 46.52], [46.96, 45.99], [49.05, 45.2], [51.23, 44.35], [53.13, 43.59], [54.94, 43.07], [56.89, 42.89], [69.68, 42.81]]; // CP-15c cup_flange profile_on_the_diagonal, R = u − 45.32 (CP-12 along_diagonal_u)
const ROX_FLANGE_FLAT_Z = 42.89; // CP-15c cup_flange flat_top_z_bed top face
const ROX_FLANGE_SPAN = 121.0; // CP-15c cup_flange plan_contour_at_bed_plus_42_3 phi_deg ±121
const ROX_CORNER_FRONT = {"long":{"intercept_mm":47.42814217654402,"slope":-0.005231149342356265},"short":{"intercept_mm":47.8577061073336,"slope":-0.005239331214842004}}; // CP-15d MODEL independent front-line fits at R050..R064, purchased physical cup/flange
const ROX_CASTING_PROUD = 0.357; // CP-15c cap_crest_line_continuation casting_crest_proud_of_the_cap_crest_by (at the joint plane)
const ROX_CASTING_INNER_Z = 41.4; // CP-15 inner_horseshoe vertical_end_face_z_bed_on_diagonal top (the casting top's height at the horseshoe edge)
const ROX_CASTING_CREST_R = 98.6; // CP-15 dome_crest_u_on_the_diagonal 143.92 − CP-12 along_diagonal_u 45.32: where the casting top reaches the dome crest
const ROX_SIDE_PIECE_PROUD = 0.092; // SP-15 pocket_rail_piece_top at_seam 43.23 − RB-04 crest 43.138
