  // the MATERIAL-IDENTITY law row holds every non-target table to main.
  const diamondShieldMat = new THREE.MeshPhysicalMaterial({
    color: 0x2e2e31, roughness: 0.56, metalness: 0.0, // DERIVED: main 97205801 literal, restored
    specularIntensity: 0.10, envMapIntensity: 0.1, // DERIVED: main 97205801 literal, restored
    clearcoat: 0.26, clearcoatRoughness: 0.32, // DERIVED: main 97205801 literal, restored
  });
  injectAnalytic(diamondShieldMat, shared, -1, 'wood');
