          let t = 0.5; // DERIVED start of the fixed-point solve for |z(t)| = outer face at y(t) (the face depends on y; 30 steps, converges in 3)
          for (let i = 0; i < 30; i++) { const y = a[1] + (b[1] - a[1]) * t; const z = a[2] + (b[2] - a[2]) * t; t += (z - zOuter(y)) / (a[2] - b[2]); }
