            const floor = new THREE.Mesh(gb(runX, zw), boxMat); floor.rotation.x = -Math.PI / 2;
            floor.position.set(midX, ySill - 0.0003, zc); // epsilon 0.3 mm under the tray support line (a seated ball never touches it)
            group.add(dm(floor, 'gullybox-floor'));
            const ceil = new THREE.Mesh(gb(runX, zw), boxMat); ceil.rotation.x = Math.PI / 2;
            ceil.position.set(midX, yLintel + 0.0003, zc); // epsilon above the lintel
            group.add(dm(ceil, 'gullybox-ceiling'));
            // the back wall opens a CHUTE MOUTH wherever a trunk's feed edge
            // (render.gully.feeds = the export's last trunk edges) crosses the
            // back plane x = inner − sgn·depth: a gap of ±60 mm about the
