            linerT.position.set(xo - sgn * ((yTop - ySillT) * tanC) - sgn * cab.wall / 2, ySillT + 0.0003, 0); // outer face at the sill's own height (lean carried) → one wall inward
            group.add(dm(linerT, sgn < 0 ? 'gullybox-reveal-trough-sill' : 'gullybox-reveal-trough-sill-f'));
