            const row = tongueRows[i], c0 = row.c, n0 = row.n;
            const span = row.station === null ? farHit(c0, n0) : row.span;
            const { base, scale } = cn8D3TongueProfile(K, row.row, span);
            // st carries positions, stv the matching uv-v so that every
