            st.push([q0, zDeck]); stv.push(6 * 0.14);
            st.push([q1, zDeck]); stv.push(7 * 0.14);
            st.push([q2, zDeck]); stv.push(8 * 0.14);
            st.push([Math.max(q2, lapIn), zDeck]); stv.push(9 * 0.14);
            st.push([Math.min(span, Math.max(q2 + 1e-6, span - lap)), zDeck]); stv.push(10 * 0.14);
            st.push([span, zDeck]); stv.push(11 * 0.14);
