    put(shades, shadowMat, 'obPocketShade');
    put(mshades, mouthShadeMat, 'obPocketMouthShade'); // W10 rim occlusion
    // 489 ENV ROUND: the under-frame boards live behind the bay (the
    // reference shows the void dark) — derived transport attribute
    {
      if (boards.length) {
        const mergedB = mergeGeoms(boards);
        snkApplyOccl(mergedB, snkBayOcclSampler(G, fcx.cups));
        const mB = new THREE.Mesh(mergedB, apronMat);
        mB.name = 'obPocketBoard';
        group.add(mB);
      }
    }
    put(strapPlates, plateBrassMat, 'obPocketStrapPlate'); // W14 E20; W15 P5 finish
    // 489 PASS-2 CURE (B14b): the studded gather ring rides the polished
    // plate brass (warm-room env response — never brassMat's green-GI leg)
    // 489 PASS-3 CURE (C3/B3, ring leg): the gather ring hangs in the
    // boot's FULL transport shadow — the polished plate response (rough
    // 0.3, emissive floor 0.22) mirrored the dark bay and read BLACK in
    // the shipped video (zero brass anywhere; live probe: lifting the
    // warm emissive floor made the ring's through-knit glints and the
    // below-band sliver read gold at the orbit registers). Its own
