    const gatherBrassMat = new THREE.MeshStandardMaterial({
      color: 0xc79b3f, roughness: 0.5, metalness: 0.7,
      envMapIntensity: 0.5,
      // 0.62: reads warm through the knit holes + the below-band sliver
      // at the orbit registers (LOOK-verified); still well under the
      // B11 "lit gold cube" ceiling lesson (0.85 read as glowing).
      emissive: 0xb98a2c, emissiveIntensity: 0.62 });
    injectAnalytic(gatherBrassMat, shared, -1, false,
      { cloth: false, gi: false, warmEnv: true });
    put(gatherIron, gatherBrassMat, 'obPocketRingGather');
    { const mT = put(tracks, trackMat, 'obPocketTrack'); if (mT) mT.userData.obChutes = slideChutes; } // R3-SNK-BODY-1: the six chutes' 24 wires (E20 family; was the W14/W15 decorative tubes); SNK-R33: their record for the census + the export
    put(slideRings, gatherBrassMat, 'obSnkSlideRing'); // R3-SNK-BODY-1: the slide rings (brass, warm-room class)
    // (the rev-11 scalloped valances are RETIRED here: the corner boot's
    // own wrap-down covers the corner face — c5259957376 §1d — and the
    // middle skirt is the cream leather's own scalloped bottom, built
